<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use PHPUnit\Framework\Attributes\DataProvider;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Security\AccessTokenClaims;

/**
 * Checks any resource server applies with the claims of the token alone.
 */
final class AccessTokenClaimsUnitTest extends TestCase
{
    public function testAcceptsAnActiveTokenForTheAudienceWithIssuerAndTenant(): void
    {
        $claims = $this->claims();

        AccessTokenClaims::assertActive($claims);
        AccessTokenClaims::assertAudience($claims, ['api']);
        AccessTokenClaims::assertAudience($claims, []);
        AccessTokenClaims::assertIssuerAndTenant($claims);

        $this->addToAssertionCount(4);
    }

    /** @return array<string, array{\Closure(array<string, mixed>): void, array<string, mixed>}> */
    public static function rejected(): array
    {
        $active = AccessTokenClaims::assertActive(...);
        $audience = static fn (array $claims) => AccessTokenClaims::assertAudience($claims, ['api']);
        $identity = AccessTokenClaims::assertIssuerAndTenant(...);
        return [
            'expired' => [$active, ['exp' => time() - 1]],
            'without exp' => [$active, ['exp' => null]],
            'not yet valid' => [$active, ['nbf' => time() + 60]],
            'without aud' => [$audience, ['aud' => null]],
            'none of the audiences' => [$audience, ['aud' => ['other']]],
            'without iss' => [$identity, ['iss' => null]],
            'empty tenant' => [$identity, ['tenant' => '']],
            'without tenant' => [$identity, ['tenant' => null]],
        ];
    }

    /** @param array<string, mixed> $override */
    #[DataProvider('rejected')]
    public function testRejects(\Closure $check, array $override): void
    {
        $this->expectException(UnauthorizedException::class);

        $check($this->claims($override));
    }

    /**
     * @param array<string, mixed> $override
     * @return array<string, mixed>
     */
    private function claims(array $override = []): array
    {
        return array_filter([
            'iss' => 'https://idp/oauth/openid/acme',
            'aud' => ['client', 'api'],
            'tenant' => 'acme',
            'nbf' => time() - 10,
            'exp' => time() + 600,
            ...$override,
        ], static fn (mixed $value): bool => $value !== null);
    }
}
